    // single public function with all test logic
    // caller (tester) provides an address 'caller' which will perform the intermediate call
    // and an amount to ensure no msg.value use; we don't send Ether here.
    function run(address intermediate) public {
        // require intermediate is a contract (has code) to ensure msg.sender != tx.origin
        // We check that intermediate != msg.sender to ensure there's an intermediate caller
        require(intermediate != msg.sender, "intermediate must differ from caller");
        // We require intermediate to be a contract by checking its code size
        uint256 size;
        assembly { size := extcodesize(intermediate) }
        require(size > 0, "intermediate must be a contract with code");

        // The test assumes that the intermediate contract has a function that calls c.owned().
        // We invoke that function using a generic call; the intermediate contract should forward the call to c.owned().
        // Build calldata for owned(): function owned() public onlyOwner { owner = payable(msg.sender); }
        bytes memory payload = abi.encodeWithSignature("callOwned(address)", address(c));
        // Call intermediate: it must perform the call to c.owned() using its own contract context
        (bool ok, ) = intermediate.call(payload);
        require(ok, "intermediate call failed");

        // After the intermediate contract invoked c.owned(), the owner should be the intermediate (msg.sender of that call)
        // On P (which uses msg.sender), owner == intermediate. On M (which uses tx.origin), owner == original tx origin (this tester)
        address observedOwner = c.owner();
        assert(observedOwner == intermediate);
    }

    // fallback to accept arbitrary calls (not used by test caller)
    fallback() external payable {}
    receive() external payable {}
}

