        vm.deal(eoaActor, 1 ether);

        // Deploy a minimal intermediary contract that will call c.burn(...) when triggered.
        // This ensures the call chain is: EOA (tx.origin) -> Intermediary (msg.sender) -> c.burn
        Intermediary inter = new Intermediary(c);

        // Ensure EOA is the tx.origin by performing the call as that actor
        vm.prank(eoaActor);
        // perform the call; burnAmount can be any value (including 0). The call may succeed or revert depending on balances/owner
        // We don't expect revert here necessarily; we just want to ensure the call path happens.
        try inter.callBurn(burnAmount) {
            // no-op on success
        } catch {
            // ignore revert; property concerns owner after call attempts as well
        }

        // The reference contract: owner was set in constructor to the deployer (address(this) in setUp via forge test runner),
        // and calling burn (even via intermediary) should NOT change owner for the correct contract.
