// Intermediary contract that simply forwards a call to c.burn. This creates a call chain where
// tx.origin is the EOA that initiated the transaction, while msg.sender inside c is the intermediary.
contract Intermediary {
    C immutable c;
    constructor(C _c) { c = _c; }
    function callBurn(uint256 amt) external {
        // forward the call; this will set msg.sender inside C to this intermediary contract,
        // and tx.origin will be the original EOA that initiated the transaction.
        c.burn(amt);
    }
