        address helperAddr;
        assembly {
            helperAddr := create2(0, add(initCode, 0x20), mload(initCode), salt)
        }
        // If create2 returned address(0) (very unlikely), deploy normally
        if (helperAddr == address(0)) {
            HelperCaller h = new HelperCaller();
            helperAddr = address(h);
        }

        HelperCaller helper = HelperCaller(payable(helperAddr));

        // Ensure the deployer (this test) has some tokens to burn by minting to this contract via owner
        // The constructor gave deployer (this) the totalSupply, so burn will be attempted from this contract.

        // Transfer ownership operations: the contract's owner getter should remain equal to the deployer (this)
        address ownerBefore = c.owner();

        // Make sure this contract has enough balance to call burn via allowed path: the burn function is onlyOwner
        // So we must call burn as the owner (this contract). The test contract is the deployer (owner) so we can call it directly.
        // Call burn from this contract (msg.sender == owner). Use fuzzed burnAmount but cap to balance to avoid revert.
        uint256 balance = c.balanceOf(address(this));
        uint256 amount = burnAmount;
        if (amount > balance) amount = balance;

        // Perform the burn as the owner
        bool ok;
        try c.burn(amount) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }
        // After calling burn, the owner must remain the deployer (no change)
        // We assert that getter equals ownerBefore. This is the single assertion.
        assertTrue(c.owner() == ownerBefore);

