        // We call helper.callOwned(c) as an EOA (prank as a different externally owned address) so tx.origin will be that EOA
        // but msg.sender for owned() will be the helper contract; this distinguishes msg.sender vs tx.origin.
        address eoa = address(uint160(uint256(keccak256(abi.encodePacked(attackerSelector, block.timestamp)))));
        vm.deal(eoa, 1 ether);
        vm.prank(eoa);
        helper.callOwned{value: 0}(address(c));

