contract HelperCaller {
    // minimal helper that calls owned() on target contract
    fallback() external payable {}
    receive() external payable {}
    function callOwned(address target) external payable {
        // target is expected to implement owned()
        (bool s, ) = target.call(abi.encodeWithSignature("owned()"));
        require(s);
    }
}

