pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // fuzzed params: an arbitrary caller address and an arbitrary burn amount
    function testFuzz_property(address caller, uint256 burnAmount) public {
        // Keep caller non-zero to be an admissible EOA
        vm.assume(caller != address(0));
        // Give caller some funds and also ensure owner has funds (constructor gave owner totalSupply=0 here, so first mint to owner)
        // mint some tokens to owner and to caller to create admissible balances
        // Owner is the test contract deployer address (address(this) in setUp), but c.owner() is public getter
        address owner = address(this);

        // Ensure wide domain for burnAmount but not overflow when minting: bound burnAmount to reasonable cap
        burnAmount = bound(burnAmount, 0, type(uint256).max / 4);

        // Mint tokens to caller and owner so burn can succeed if attempted
        // Only owner can call mintToken, so use vm.prank to act as owner
        vm.prank(owner);
        c.mintToken(caller, burnAmount);
        vm.prank(owner);
        c.mintToken(owner, burnAmount);

        // Record totalSupply before any burn
        uint256 totalBefore = c.totalSupply();

        // Attempt to burn as the fuzzed caller
        bool ok;
        // make the call from caller EOA
        vm.prank(caller);
        try c.burn(burnAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, read totalSupply
        uint256 totalAfter = c.totalSupply();

        // General rule (single assertion): If caller is not the owner, totalSupply must remain unchanged
        // The reference contract enforces that only owner can burn, so for all inputs this holds; the mutant breaks it.
        if (caller != owner) {
            assertTrue(totalAfter == totalBefore);
        } else {
            // If caller is owner, burn should succeed and reduce totalSupply by burnAmount
            // Accept either success or failure depending on burnAmount (but ensure invariant of reduction when ok)
            if (ok) {
                assertTrue(totalAfter == totalBefore - burnAmount);
            } else {
                // If it reverted, totalSupply must be unchanged
                assertTrue(totalAfter == totalBefore);
            }
        }
    }
}
